Issue description
If you allocate memory on the GPU using cuMemAlloc, then tensorFromBlob will fail on it. If you use cudaMalloc, it will succeed.
More generally, is the CUDA Driver API actually supported in Pytorch, or is it only the Runtime API? The actual error appears to occur when cudaPointerGetAttributes is called on the data pointer.
Code example
Using cpp_extension, if you have the following C++ code:
#include <torch/torch.h>
#include <cuda.h>
#include <cuda_runtime.h>

using namespace at;
using namespace std;

Tensor load() {
  CUdeviceptr data_done;
  CUdevice handle;
  cuDeviceGet(&handle, 0);
  CUcontext context_;
  cuCtxCreate(&context_, 0, handle);
  CUresult err = cuMemAlloc(&data_done, 16*sizeof(float));
  auto f = torch::CUDA(kFloat).tensorFromBlob(reinterpret_cast<void*>(data_done), {16});
  return f;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("load", &load, "load data");
}

Then when load is called in python, it will fail with:
THCudaCheck FAIL file=/home/devbox/projects/pytorch/aten/src/THC/generic/THCStorage.c line=150 error=49 : incompatible driver context
---------------------------------------------------------------------------
RuntimeError                              Traceback (most recent call last)
<ipython-input-3-e8b40809576d> in <module>()
----> 1 pyt.load()

RuntimeError: cuda runtime error (49) : incompatible driver context at /home/devbox/projects/pytorch/aten/src/THC/generic/THCStorage.c:150
However, if you use cudaMalloc as below, then it will succeed:
#include <torch/torch.h>
#include <cuda.h>
#include <cuda_runtime.h>

using namespace at;
using namespace std;

Tensor load() {
  CUdeviceptr data_done;
  cudaError_t err2 = cudaMalloc(reinterpret_cast<void**>(&data_done), 16*sizeof(float));
  auto f = torch::CUDA(kFloat).tensorFromBlob(reinterpret_cast<void*>(data_done), {16});
  return f;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("load", &load, "load data");
}

